        Pose centreLaneToLeftLaunchCatchControl2 = p.of(61.3, 40.2, 0);
        Pose centreLaneToLeftLaunchCatchControl3 = p.of(62.5, 45.6, 0);
        Pose centreLaneToLeftLaunchCatchControl4 = p.of(62.9, 83.6, 0);
        Pose centreLaneToLeftLaunchCatchSegment1Start = p.of(57.5, 123.5, 180);
        Pose centreLaneToLeftLaunchCatchSegment1End = p.of(57.5, 123.5, 270);
        Pose centreLaneToLeftLaunchCatchSegment2Heading = p.of(57.5, 123.5, 270);
